<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar na corrida</title><style>body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}main{max-width:520px;margin:12vh auto;padding:28px}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:24px}h1{font-size:48px;letter-spacing:-.06em;line-height:.95}label{font-weight:800;display:block;margin:18px 0 8px}input{font:inherit;padding:13px;width:100%;box-sizing:border-box;border:2px solid #dbe5e8;border-radius:12px}button{font:inherit;font-weight:900;border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;margin-top:16px;cursor:pointer}.muted{color:#637780;font-size:14px}.ok{background:#d8f4d8;border-radius:12px;padding:14px;margin-top:16px}</style></head><body><main><div class="panel"><div>🦆 PATO NA PISTA</div><h1>Entre na corrida</h1><p class="muted">Sala {{ $code }} · cada celular pode se inscrever uma vez.</p><label for="name">Seu nome</label><input id="name" placeholder="Ex.: Camila Souza" autofocus><button id="join">Entrar na corrida</button><p id="msg" class="muted"></p></div></main><script>const key='duck-race-session-{{ $code }}',session=localStorage.getItem(key)||crypto.randomUUID();localStorage.setItem(key,session);document.getElementById('join').onclick=async()=>{const name=document.getElementById('name').value.trim(),msg=document.getElementById('msg'),btn=document.getElementById('join');if(!name){msg.textContent='Digite seu nome.';return}btn.disabled=true;const r=await fetch('/api/races/{{ $code }}/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,session})});const data=await r.json();if(r.ok){msg.className='ok';msg.textContent='✅ Você entrou na sala como '+name+'! Aguarde o organizador começar a corrida.';document.getElementById('name').disabled=true;btn.textContent='Inscrito';}else{btn.disabled=false;msg.textContent=data.message||'Não foi possível entrar.'}}</script></body></html>
